    31	#include "idn2.h"
    32	#include "tables.h"
    33	#include <unictype.h>           /* uc_combining_class, UC_CCC_VR */
    34	#include "context.h"
    35	
    36	int
    37	_idn2_contextj_rule (const uint32_t * label, size_t llen, size_t pos)
    38	{
    39	  uint32_t cp;
    40	
    41	  if (llen == 0)
    42	    return IDN2_OK;
    43	
    44	  cp = label[pos];
    45	
    46	  if (!_idn2_contextj_p (cp))
    47	    return IDN2_OK;
    48	
    49	  switch (cp)
    50	    {
    51	    case 0x200C:                /* ZERO WIDTH NON-JOINER */
    52	      if (pos > 0)
    53	        {
    54	          /* If Canonical_Combining_Class(Before(cp)) .eq.  Virama Then True; */
    55	          uint32_t before_cp = label[pos - 1];
    56	          int cc = uc_combining_class (before_cp);
    57	          if (cc == UC_CCC_VR)
    58	            return IDN2_OK;
    59	        }
    60	
    61	      /* See http://permalink.gmane.org/gmane.ietf.idnabis/6980 for
    62	         clarified rule. */
    63	
    64	      if (pos == 0 || pos == llen - 1)
    65	        return IDN2_CONTEXTJ;
    66	
    67	      {
    68	        int jt;
    69	        size_t tmp;
    70	
    71	        /* Search backwards. */
    72	        for (tmp = pos - 1;; tmp--)
    73	          {
    74	            jt = uc_joining_type (label[tmp]);
    75	            if (jt == UC_JOINING_TYPE_L || jt == UC_JOINING_TYPE_D)
    76	              break;
    77	            if (tmp == 0)
    78	              return IDN2_CONTEXTJ;
    79	            if (jt == UC_JOINING_TYPE_T)
    80	              continue;
    81	            return IDN2_CONTEXTJ;
    82	          }
    83	
    84	        /* Search forward. */
    85	        for (tmp = pos + 1; tmp < llen; tmp++)
    86	          {
    87	            jt = uc_joining_type (label[tmp]);
    88	            if (jt == UC_JOINING_TYPE_R || jt == UC_JOINING_TYPE_D)
    89	              break;
    90	            if (tmp == llen - 1)
    91	              return IDN2_CONTEXTJ;
    92	            if (jt == UC_JOINING_TYPE_T)
    93	              continue;
    94	            return IDN2_CONTEXTJ;
    95	          }
    96	      }
    97	
    98	      return IDN2_OK;
    99	      break;
   100	
   101	    case 0x200D:                /* ZERO WIDTH JOINER */
   102	      if (pos > 0)
   103	        {
   104	          uint32_t before_cp = label[pos - 1];
   105	          int cc = uc_combining_class (before_cp);
   106	          if (cc == UC_CCC_VR)
   107	            return IDN2_OK;
   108	        }
   109	      return IDN2_CONTEXTJ;
   110	    }
   111	
   112	  return IDN2_CONTEXTJ_NO_RULE;
   113	}
   114	
   115	static const char *
   116	_uc_script_name (ucs4_t uc)
   117	{
   118	  const uc_script_t *ucs = uc_script(uc);
   119	
   120	  if (!ucs)
   121	    return "";
   122	
   123	  return ucs->name;
   124	}
   125	
   126	int
   127	_idn2_contexto_rule (const uint32_t * label, size_t llen, size_t pos)
   128	{
   129	  uint32_t cp = label[pos];
   130	
   131	  if (!_idn2_contexto_p (cp))
   132	    return IDN2_OK;
   133	
   134	  switch (cp)
   135	    {
   136	    case 0x00B7:
   137	      /* MIDDLE DOT */
   138	      if (llen < 3)
   139	        return IDN2_CONTEXTO;
   140	      if (pos == 0 || pos == llen - 1)
   141	        return IDN2_CONTEXTO;
   142	      if (label[pos - 1] == 0x006C && label[pos + 1] == 0x006C)
   143	        return IDN2_OK;
   144	      return IDN2_CONTEXTO;
   145	      break;
   146	
   147	    case 0x0375:
   148	      /* GREEK LOWER NUMERAL SIGN (KERAIA) */
   149	      if (pos == llen - 1)
   150	        return IDN2_CONTEXTO;
   151	      if (strcmp (_uc_script_name (label[pos + 1]), "Greek") == 0)
   152	        return IDN2_OK;
   153	      return IDN2_CONTEXTO;
   154	      break;
   155	
   156	    case 0x05F3:
   157	      /* HEBREW PUNCTUATION GERESH */
   158	    case 0x05F4:
   159	      /* HEBREW PUNCTUATION GERSHAYIM */
   160	      if (pos == 0)
   161	        return IDN2_CONTEXTO;
   162	      if (strcmp (_uc_script_name (label[pos - 1]), "Hebrew") == 0)
   163	        return IDN2_OK;
   164	      return IDN2_CONTEXTO;
   165	      break;
   166	
   167	    case 0x0660:
   168	    case 0x0661:
   169	    case 0x0662:
   170	    case 0x0663:
   171	    case 0x0664:
   172	    case 0x0665:
   173	    case 0x0666:
   174	    case 0x0667:
   175	    case 0x0668:
   176	    case 0x0669:
   177	      {
   178	        /* ARABIC-INDIC DIGITS */
   179	        size_t i;
   180	        for (i = 0; i < llen; i++)
   181	          if (label[i] >= 0x6F0 && label[i] <= 0x06F9)
   182	            return IDN2_CONTEXTO;
   183	        return IDN2_OK;
   184	        break;
   185	      }
   186	
   187	    case 0x06F0:
   188	    case 0x06F1:
   189	    case 0x06F2:
   190	    case 0x06F3:
   191	    case 0x06F4:
   192	    case 0x06F5:
   193	    case 0x06F6:
   194	    case 0x06F7:
   195	    case 0x06F8:
   196	    case 0x06F9:
   197	      {
   198	        /* EXTENDED ARABIC-INDIC DIGITS */
   199	        size_t i;
   200	        for (i = 0; i < llen; i++)
   201	          if (label[i] >= 0x660 && label[i] <= 0x0669)
   202	            return IDN2_CONTEXTO;
   203	        return IDN2_OK;
   204	        break;
   205	      }
   206	    case 0x30FB:
   207	      {
   208	        /* KATAKANA MIDDLE DOT */
   209	        size_t i;
   210	        bool script_ok = false;
   211	
   212	        for (i = 0; !script_ok && i < llen; i++)
   213	          if (strcmp (_uc_script_name (label[i]), "Hiragana") == 0
   214	              || strcmp (_uc_script_name (label[i]), "Katakana") == 0
   215	              || strcmp (_uc_script_name (label[i]), "Han") == 0)
   216	            script_ok = true;
   217	
   218	        if (script_ok)
   219	          return IDN2_OK;
   220	        return IDN2_CONTEXTO;
   221	        break;
   222	      }
   223	    }
   224	
   225	  return IDN2_CONTEXTO_NO_RULE;
   226	}
   227	
   228	bool
   229	_idn2_contexto_with_rule (uint32_t cp)
   230	{
   231	  switch (cp)
   232	    {
   233	    case 0x00B7:
   234	      /* MIDDLE DOT */
   235	    case 0x0375:
   236	      /* GREEK LOWER NUMERAL SIGN (KERAIA) */
   237	    case 0x05F3:
   238	      /* HEBREW PUNCTUATION GERESH */
   239	    case 0x05F4:
   240	      /* HEBREW PUNCTUATION GERSHAYIM */
   241	    case 0x0660:
   242	    case 0x0661:
   243	    case 0x0662:
   244	    case 0x0663:
   245	    case 0x0664:
   246	    case 0x0665:
   247	    case 0x0666:
   248	    case 0x0667:
   249	    case 0x0668:
   250	    case 0x0669:
   251	      /* ARABIC-INDIC DIGITS */
   252	    case 0x06F0:
   253	    case 0x06F1:
   254	    case 0x06F2:
   255	    case 0x06F3:
   256	    case 0x06F4:
   257	    case 0x06F5:
   258	    case 0x06F6:
   259	    case 0x06F7:
   260	    case 0x06F8:
   261	    case 0x06F9:
   262	      /* EXTENDED ARABIC-INDIC DIGITS */
   263	    case 0x30FB:
   264	      /* KATAKANA MIDDLE DOT */
   265	      return true;
   266	      break;
   267	    }
   268	
   269	  return false;
   270	}
